$stmt=$pdo->prepare('SELECT COUNT(*) AS votes, AVG(score) AS average_score FROM recipe_ratings WHERE recipe_id=?');$stmt->execute([$id]);$ratingSummary=$stmt->fetch();
$myScore=0;$isSaved=false;
if($detailMember){
    $stmt=$pdo->prepare('INSERT INTO recipe_views(user_id,recipe_id,last_viewed_at) VALUES(?,?,CURRENT_TIMESTAMP(6)) ON DUPLICATE KEY UPDATE last_viewed_at=CURRENT_TIMESTAMP(6)');$stmt->execute([$detailMember['id'],$id]);
    $stmt=$pdo->prepare('SELECT score FROM recipe_ratings WHERE user_id=? AND recipe_id=?');$stmt->execute([$detailMember['id'],$id]);$myScore=(int)$stmt->fetchColumn();
    $stmt=$pdo->prepare('SELECT recipe_id FROM favorites WHERE user_id=? AND recipe_id=?');$stmt->execute([$detailMember['id'],$id]);$isSaved=(bool)$stmt->fetchColumn();
}
$stmt=$pdo->prepare('SELECT cm.*,COALESCE(NULLIF(p.display_name,\'\'),u.username) AS author FROM recipe_comments cm JOIN users u ON u.id=cm.user_id LEFT JOIN user_profiles p ON p.user_id=u.id WHERE cm.recipe_id=? ORDER BY cm.created_at DESC,cm.id DESC LIMIT 100');$stmt->execute([$id]);$comments=$stmt->fetchAll();
$communityFlash=$_SESSION['community_flash'] ?? '';unset($_SESSION['community_flash']);
